import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.Di-jvWLj.js";const u=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ui.md","filePath":"guide/ui.md","lastUpdated":1793383610000}'),o={name:"guide/ui.md"};function r(d,e,i,l,c,p){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><p><code>@chamvi/ui</code> is a dashboard for the agents of an app: see what each agent does, start a run, watch runs live, answer approvals, look into agent state and see when cron subscriptions fire next. It is a prebuilt Vue 3 app (vuecs, the Crimson design) that your own <code>@chamvi/http</code> app serves on the same origin, so there is no CORS and no second deployment.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#E6DFDE;">npm </span><span style="color:#E7C58C;">install</span><span style="color:#E7C58C;"> @chamvi/ui</span><span style="color:#E7C58C;"> --save</span></span></code></pre></div><p><code>uiRoutes()</code> returns the extra routes for <code>createHttpApp({ routes })</code>:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">return</span><span style="color:#E6DFDE;"> createHttpApp({</span></span>
<span class="line"><span style="color:#E6DFDE;">    engine,</span></span>
<span class="line"><span style="color:#E6DFDE;">    auth: [staticTokens({</span></span>
<span class="line"><span style="color:#E6DFDE;">        tokens: [{</span></span>
<span class="line"><span style="color:#E6DFDE;">            value: process.env.ADMIN_TOKEN</span><span style="color:#FF7B84;">!</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            id: </span><span style="color:#E7C58C;">&#39;admin&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            permissions: [</span><span style="color:#E7C58C;">&#39;*&#39;</span><span style="color:#E6DFDE;">],</span></span>
<span class="line"><span style="color:#E6DFDE;">        }],</span></span>
<span class="line"><span style="color:#E6DFDE;">    })],</span></span>
<span class="line"><span style="color:#958A8B;">    // the dashboard at /ui, signed in with a pasted bearer token</span></span>
<span class="line"><span style="color:#E6DFDE;">    routes: uiRoutes(),</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p>Open <code>/ui/</code> and paste a token; the dashboard opens on the agents overview. Nothing of the dashboard runs on the server but one static file route; every page talks to the API it already has, with the signed-in principal&#39;s bearer token.</p><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Shows</th><th>Needs</th></tr></thead><tbody><tr><td>Agents</td><td>A card per agent: its channel chips (GitHub events, cron expressions, hook paths, http), running and waiting runs, the next cron fire, a 24 h activity strip, the last run, the budget and the state collections; a name filter; a notice listing the <a href="/guide/agent-folders">agent folders</a> that failed to load, with their messages. The landing page after sign-in.</td><td><code>run:read</code></td></tr><tr><td>Agent</td><td>The agent&#39;s budget, state collections and channel chips, Start run (with an <code>http.on()</code> subscription: a JSON payload sent to <code>POST /agents/:name/runs</code> as you) and View all runs, and four tabs: Overview (runs, failures, waiting approvals and tokens, recent runs, its waiting approvals, its subscriptions with route, hook or next fire), Runs (filtered by status), State (key-value entries and collections, read-only) and Schedules.</td><td><code>run:read</code>; <code>agent:&lt;name&gt;:run</code> to start; <code>state:read</code> for State</td></tr><tr><td>Runs</td><td>Every run, newest first (<code>GET /runs?sort=-createdAt</code>), filtered by agent and status in the address bar; running and waiting counts, failures and tokens of the last 24 h; tokens per run. Refreshes every 5 s.</td><td><code>run:read</code></td></tr><tr><td>Run</td><td>Status, budgets (steps, tokens, time), the envelope (channel, subscription, address, payload) and the step timeline (llm, tool and wait steps, inputs and outputs collapsed). Live over the run&#39;s SSE stream, including the streamed text of the step in progress. A cancel button with a confirmation.</td><td><code>run:read</code> or <code>agent:&lt;name&gt;:run</code>; <code>run:cancel</code> to cancel</td></tr><tr><td>Approvals</td><td>Each waiting run with the request&#39;s title and body, the tool, the channel it went out through, the expiry countdown and a reason field; a request with <a href="/guide/approvals#offering-options">options</a> shows them as radios (one) or checkboxes (several), each <code>detail</code> preformatted in a closed <code>Details</code> block (a diff colored by line), and Approve waits for a fitting selection; Approve or Deny (<code>POST /runs/:id/approve</code>). The sidebar shows the count.</td><td><code>run:read</code> to list, <code>agent:&lt;name&gt;:approve</code> to answer</td></tr><tr><td>Schedules</td><td>The cron subscriptions per agent with the next fire time in the subscription&#39;s time zone.</td><td><code>run:read</code></td></tr></tbody></table><p>Agent names link to the agent page from every other page. The 24 h figures come from the newest 100 runs (of the agent on its page, of the whole app on the overview and the runs page), since the API has no time filter: more runs than that in a day show <code>100+</code>. Only tools that need an approval are listed, because an agent may build its tool set per run.</p><p>A principal without the grant a page needs sees a notice naming it; the rest of the dashboard keeps working. An approval link from a channel&#39;s message needs read access to its run (<code>run:read</code> or <code>agent:&lt;name&gt;:run</code>) besides <code>agent:&lt;name&gt;:approve</code>.</p><h2 id="sign-in" tabindex="-1">Sign-in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign-in&quot;">​</a></h2><ul><li><strong>Token</strong> (default): a static bearer token of <code>staticTokens()</code>. <code>GET /me</code> checks it before it is kept, in the tab&#39;s <code>sessionStorage</code> only; sign-out removes every <code>chamvi.</code> key but a pending approval link. Only a 401 drops a stored token: a reload while the API restarts or rate limits keeps it, and the next navigation tries again.</li><li><strong>authup</strong>: <code>auth.authup</code> adds &quot;Continue with authup&quot;, the OIDC code flow with PKCE through <code>@authup/client-web-kit</code>, whose tokens are kept in the tab&#39;s <code>sessionStorage</code> (<code>chamvi.authup.*</code>), never in cookies. The authup client needs <code>&lt;origin&gt;&lt;uiBase&gt;/login/callback</code> as a redirect URI. Pair it with the app&#39;s <code>authup()</code> authenticator. <code>auth.tokens: false</code> hides the token form (then <code>auth.authup</code> is required).</li></ul><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">return</span><span style="color:#E6DFDE;"> createHttpApp({</span></span>
<span class="line"><span style="color:#E6DFDE;">    engine,</span></span>
<span class="line"><span style="color:#E6DFDE;">    basePath: </span><span style="color:#E7C58C;">&#39;/api&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    auth: [authup({ verifier })],</span></span>
<span class="line"><span style="color:#E6DFDE;">    routes: uiRoutes({</span></span>
<span class="line"><span style="color:#958A8B;">        // served at /api/console/, the API under /api</span></span>
<span class="line"><span style="color:#E6DFDE;">        basePath: </span><span style="color:#E7C58C;">&#39;/console&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        auth: {</span></span>
<span class="line"><span style="color:#E6DFDE;">            tokens: </span><span style="color:#FF7B84;">false</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">            // the authup client needs &lt;origin&gt;/api/console/login/callback as a redirect URI</span></span>
<span class="line"><span style="color:#E6DFDE;">            authup: { url: </span><span style="color:#E7C58C;">&#39;https://auth.example.com/api&#39;</span><span style="color:#E6DFDE;">, clientId: </span><span style="color:#E7C58C;">&#39;chamvi&#39;</span><span style="color:#E6DFDE;"> },</span></span>
<span class="line"><span style="color:#E6DFDE;">        },</span></span>
<span class="line"><span style="color:#E6DFDE;">    }),</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p>A revoked token or an expired authup session answers 401: the dashboard refreshes the authup session once, else signs out and returns to the sign-in page with the page it was on as the way back.</p><h2 id="approval-links" tabindex="-1">Approval links <a class="header-anchor" href="#approval-links" aria-label="Permalink to &quot;Approval links&quot;">​</a></h2><p>A channel&#39;s approval message (GitHub, OpenClaw, a channel you write) links a person straight to an approval by run, without a token: <code>&lt;origin&gt;&lt;uiBase&gt;/approvals?run=&lt;runId&gt;&amp;approval=&lt;approvalId&gt;</code> (<code>approval</code> is optional and then means the approval the run waits on when the page opens). A signed-out visit goes through sign-in, the token form or the authup round-trip, and comes back to the same URL. Signed in, the dashboard scrolls to that run&#39;s approval card, highlights and focuses it; Approve and Deny answer through <code>POST /runs/:id/approve</code> as the signed-in principal, so the link is only as powerful as the person who opens it. The page reads the run with <code>GET /runs/:id</code> (<code>run:read</code> or <code>agent:&lt;name&gt;:run</code>) and follows it with the inbox poll:</p><table tabindex="0"><thead><tr><th>The run</th><th>The page shows</th></tr></thead><tbody><tr><td>waits on that approval</td><td>the highlighted card</td></tr><tr><td>waits on another approval</td><td>a notice linking the run; the new approval is listed in the inbox</td></tr><tr><td>no longer waits (answered, finished) or the approval expired</td><td>a notice linking the run</td></tr><tr><td>waits, but the principal lacks <code>agent:&lt;name&gt;:approve</code></td><td>a 403 notice naming the grant, and the card without Approve and Deny</td></tr><tr><td>is not readable with the principal&#39;s grants</td><td>a 403 notice</td></tr><tr><td>does not exist</td><td>&quot;not found&quot;</td></tr></tbody></table><p>Every answer goes through <code>POST /runs/:id/approve</code> by approval id, as the signed-in principal; a run that moved on to another approval answers 409.</p><h2 id="serving" tabindex="-1">Serving <a class="header-anchor" href="#serving" aria-label="Permalink to &quot;Serving&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th></th></tr></thead><tbody><tr><td><code>basePath</code></td><td><code>&#39;/ui&#39;</code></td><td>The dashboard&#39;s path under the app&#39;s <code>basePath</code>, lower case</td></tr><tr><td><code>auth.tokens</code></td><td><code>true</code></td><td>Offer the token form</td></tr><tr><td><code>auth.authup</code></td><td>none</td><td><code>{ url, clientId, realmId? }</code></td></tr><tr><td><code>root</code></td><td>the package&#39;s <code>dist/app</code></td><td>Another build folder</td></tr></tbody></table><ul><li>Every <code>GET</code> below <code>basePath</code> answers a file of the build, <code>index.html</code> for any other path without an extension (the client routes), or 404. Hashed files under <code>assets/</code> are cached for a year (<code>immutable</code>), the rest <code>no-cache</code>.</li><li><code>index.html</code> gets <code>&lt;base href=&quot;&lt;uiBase&gt;/&quot;&gt;</code> and the config (<code>apiBase</code>, <code>uiBase</code>, the sign-in modes) as a JSON block, so the same build works under any <code>basePath</code>.</li><li>Paths are decoded once and refused on <code>..</code>, <code>.</code>, empty segments, backslashes, NUL and double encoding: nothing outside the build is read.</li><li>Every answer carries a Content-Security-Policy (<code>default-src &#39;self&#39;</code>, scripts only from the build, <code>connect-src</code> and <code>form-action</code> add the authup origin, <code>frame-ancestors &#39;none&#39;</code>), <code>x-content-type-options: nosniff</code>, <code>x-frame-options: DENY</code> and <code>referrer-policy: no-referrer</code>. Fonts and icons are part of the build; nothing loads from a CDN.</li><li>The route checks no credentials (the build holds no secret) and skips the rate limiter.</li></ul><p>Behind a proxy that mounts the app under a prefix, set the app&#39;s <code>basePath</code>; the dashboard follows it. Invalid options throw <code>InvalidAgentDefinitionError</code>; a missing build is reported on the first request (500 and <code>onError</code>), so the build may land later, e.g. in a container image.</p><h2 id="live-updates" tabindex="-1">Live updates <a class="header-anchor" href="#live-updates" aria-label="Permalink to &quot;Live updates&quot;">​</a></h2><p>The runs list and the inbox poll every 5 s. The run page follows <code>GET /runs/:id/stream</code> with a fetch-based reader (an <code>EventSource</code> cannot send the bearer header): after a dropped connection it reconnects with the last step index as <code>Last-Event-ID</code> (1, 2, 5, then every 10 s, or the <code>Retry-After</code> of a 503 from the stream cap), so a step is never lost or shown twice. Streamed text belongs to the model step in progress and gives way to the step once it is stored.</p>`,24)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
